import click
from click.testing import CliRunner

# Test 1: Shadowed help option - should suggest the non-shadowed one
@click.group(context_settings={"help_option_names": ["-h", "--help"]})
def cli1():
    pass

@cli1.command()
@click.option("--help-file", "-h")
@click.argument("required")
def sub1(help_file, required):
    pass

runner = CliRunner()
print("Test 1: Shadowed -h, should suggest --help")
result = runner.invoke(cli1, ["sub1"])
print(result.output)
assert "Try 'cli1 sub1 --help' for help." in result.output
print("✓ Test 1 passed\n")

# Test 2: All help options shadowed - should show no hint
@click.group(context_settings={"help_option_names": ["-h", "--help"]})
def cli2():
    pass

@cli2.command()
@click.option("--help", "-h")
@click.argument("required")
def sub2(help, required):
    pass

print("Test 2: All help options shadowed, should show no hint")
result = runner.invoke(cli2, ["sub2"])
print(result.output)
assert "Try 'cli2 sub2" not in result.output
print("✓ Test 2 passed\n")

# Test 3: Prefer longer help option name
@click.group(context_settings={"help_option_names": ["-h", "--help"]})
def cli3():
    pass

@cli3.command()
@click.option("--help-file", "-h")
@click.argument("required")
def sub3(help_file, required):
    pass

print("Test 3: Both help options available, prefer longer --help")
result = runner.invoke(cli3, ["sub3"])
print(result.output)
assert "Try 'cli3 sub3 --help' for help." in result.output
print("✓ Test 3 passed\n")

# Test 4: Custom help option names with shadowing
@click.group(context_settings={"help_option_names": ["/?", "--help"]})
def cli4():
    pass

@cli4.command()
@click.option("--help", is_flag=True)
@click.argument("required")
def sub4(help, required):
    pass

print("Test 4: Custom help option names with shadowing")
result = runner.invoke(cli4, ["sub4"])
print(result.output)
assert "Try 'cli4 sub4 /?' for help." in result.output
print("✓ Test 4 passed\n")

print("All tests passed!")
EOF
